(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.01-t*0.15)*8 + Math.cos((y+w1y)*0.012+t*0.1)*6;
  const w2y = Math.cos((y+w1y)*0.01+t*0.12)*8 + Math.sin((x+w1x)*0.011-t*0.18)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.6],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.75],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.65],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.55],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.085,1.8,0.7],
    [200+Math.sin(t*0.25+1)*110,220+Math.cos(t*0.45+3)*60,0.075,2.4,0.6],
    [300+Math.cos(t*0.7+4)*90,100+Math.sin(t*0.5+2)*70,0.095,1.6,0.8]
  ];
  let aS=0,iS=0,tW=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=(Math.sin(d*f-t*sp)+Math.sin(d*f*1.618-t*sp*0.618)*0.5)*w;
    iS+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f*1.2+t*sp*0.8+3.0)*0.4)*w;
    tW+=w;
  }
  const act=aS/tW,inh=iS/tW;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.07-sy*0.05+t*1.3)+Math.cos(sx*0.05+sy*0.06-t*0.9))/2;
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg=bg1*0.5+bg2*0.3+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3+Math.sin(dist*0.065-ang*5.618-t*0.8)*0.6+Math.sin(dist*0.035+ang*2.618+t*1.0)*0.5;
  const cell=(Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin(sx*0.08+1.7)*Math.sin(sy*0.08+2.3)*0.6+Math.sin((sx+sy)*0.1+t)*0.5)*0.4;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral*0.4)*2.2);
  const laplacian=bg1-bg2*0.5+Math.sin(sx*0.02+sy*0.03+t*0.5)*0.3;
  const turing=Math.tanh((reaction+laplacian*0.6-reaction*reaction*0.3)*2.0);
  const cellM=Math.tanh(cell*1.5)*0.3;
  const blend=turing*0.6+cellM*0.2+reaction*0.2;
  const v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,85],[15,70,120],[20,115,135],[30,160,140],[120,185,100],[210,195,60],[230,150,50],[215,95,55],[185,55,70],[130,35,85],[70,20,65],[35,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=Math.min(idx-i+Math.sin(t*0.15)*0.03,1);
  const pulse=0.85+Math.sin(t*0.4)*0.05+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(turing)>0.75?1.2:(Math.abs(turing)>0.4?1.05:0.95);
  const lum=pulse*edge;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)*0.001;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*vig)|0
  ];
}
